//! Versioned compact binary envelope codec with strict bounds.
use lcf_core::Envelope;use std::io;
const MAGIC:&[u8;4]=b"LCF1";const MAX_ID:usize=128;const MAX_PAYLOAD:usize=65_507;
fn take<'a>(b:&'a[u8],p:&mut usize,n:usize)->io::Result<&'a[u8]>{let e=(*p).checked_add(n).ok_or_else(||io::Error::new(io::ErrorKind::InvalidData,"overflow"))?;if e>b.len(){return Err(io::Error::new(io::ErrorKind::UnexpectedEof,"truncated frame"));}let s=&b[*p..e];*p=e;Ok(s)}
fn put_string(o:&mut Vec<u8>,s:&str)->io::Result<()>{if s.len()>MAX_ID{return Err(io::Error::new(io::ErrorKind::InvalidInput,"identity too long"));}o.extend_from_slice(&(s.len()as u16).to_be_bytes());o.extend_from_slice(s.as_bytes());Ok(())}
fn get_string(b:&[u8],p:&mut usize)->io::Result<String>{let n=u16::from_be_bytes(take(b,p,2)?.try_into().unwrap())as usize;if n>MAX_ID{return Err(io::Error::new(io::ErrorKind::InvalidData,"identity too long"));}String::from_utf8(take(b,p,n)?.to_vec()).map_err(|_|io::Error::new(io::ErrorKind::InvalidData,"invalid utf-8"))}
pub fn encode(e:&Envelope)->io::Result<Vec<u8>>{if e.payload.len()>MAX_PAYLOAD{return Err(io::Error::new(io::ErrorKind::InvalidInput,"payload too large"));}let mut o=Vec::with_capacity(64+e.payload.len());o.extend_from_slice(MAGIC);o.extend_from_slice(&e.id);put_string(&mut o,&e.source)?;put_string(&mut o,&e.destination)?;o.extend_from_slice(&e.created_at_ms.to_be_bytes());o.extend_from_slice(&e.expires_at_ms.to_be_bytes());o.push(e.hop_limit);o.extend_from_slice(&(e.payload.len()as u32).to_be_bytes());o.extend_from_slice(&e.payload);Ok(o)}
pub fn decode(b:&[u8])->io::Result<Envelope>{let mut p=0;if take(b,&mut p,4)?!=MAGIC{return Err(io::Error::new(io::ErrorKind::InvalidData,"bad magic/version"));}let id=take(b,&mut p,16)?.try_into().unwrap();let source=get_string(b,&mut p)?;let destination=get_string(b,&mut p)?;let created_at_ms=u64::from_be_bytes(take(b,&mut p,8)?.try_into().unwrap());let expires_at_ms=u64::from_be_bytes(take(b,&mut p,8)?.try_into().unwrap());let hop_limit=take(b,&mut p,1)?[0];let n=u32::from_be_bytes(take(b,&mut p,4)?.try_into().unwrap())as usize;if n>MAX_PAYLOAD{return Err(io::Error::new(io::ErrorKind::InvalidData,"payload too large"));}let payload=take(b,&mut p,n)?.to_vec();if p!=b.len(){return Err(io::Error::new(io::ErrorKind::InvalidData,"trailing bytes"));}Ok(Envelope{id,source,destination,created_at_ms,expires_at_ms,hop_limit,payload})}
#[cfg(test)]mod tests{use super::*;#[test]fn round_trip(){let e=Envelope{id:[3;16],source:"a".into(),destination:"b".into(),created_at_ms:1,expires_at_ms:8,hop_limit:3,payload:b"hi".to_vec()};assert_eq!(decode(&encode(&e).unwrap()).unwrap(),e);}
#[test]fn rejects_truncation(){assert!(decode(b"LCF1").is_err());}}
